head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > footerDiv]<br/>웹접근성 향상을 위해 컴포넌트의 하단 Footer 영역을 div 태그로 렌더링할지 설정합니다.",
    "validation" : [
        "미설정(기본값 false) 시 Footer 영역이 'table' 태그로 렌더링됩니다.",
        "false 설정 시 Footer 영역이 'table' 태그로 렌더링되며 내부 요소가 'tr', 'td' 셀로 배치됩니다.",
        "false 설정 시 내부 요소에 '_div' 접미사 CSS 클래스가 적용되지 않습니다.",
        "true 설정 시 Footer 영역이 'div' 태그로 렌더링되며 내부 요소가 'span', 'div', 'button', 'a' 등으로 직접 배치됩니다.",
        "true 설정 시 각 요소에 '_div' 접미사가 붙은 CSS 클래스(예: w2calendar_go_today_div, w2calendar_footer_date_div, w2calendar_date_cancel_div)가 추가됩니다.",
        "true 설정 시 topLayout 속성은 무시되고 Today 버튼이 항상 Footer 에 표시됩니다.",
        "accessibility=true 이면 footerDiv 속성이 true 로 강제 설정됩니다.",
        "footerDiv=false, calendarValueType=yearMonthDate 일 때 topLayout=true 이면 Today 버튼이 Footer 가 아닌 Header 에 배치됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        footerDiv : con_footerDiv.getText(),
        accessibility : con_accessibility.getText(),
        calendarValueType : con_calendarValueType.getText(),
        topLayout : con_topLayout.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// [공통] 적용된 footerDiv 값 + accessibility 강제 적용 여부
scwin.getAppliedFooterDiv = function () {
    let footerDivOpt = target1.options.footerDiv;
    let acc = target1.options.accessibility;
    // validation: accessibility=true 이면 footerDiv 가 true 로 강제 설정됨
    let forced = (acc === true && footerDivOpt === true) ? ' (accessibility=true → footerDiv=true 강제 적용)' : '';
    wf_body_bottom.getObj("scwin").setReturnValue("[적용된 footerDiv 값] " + footerDivOpt + forced);
}



// [공통] Footer 영역 레이아웃 (table / div) - footerDiv 속성의 핵심 동작
scwin.getFooterLayout = function () {
    let calendarRender = target1.render;

    let footerDivEl = calendarRender.querySelector('div.w2calendar_footer, div[class*="w2calendar_footer"]:not(table)');
    let footerTableEl = calendarRender.querySelector('table.w2calendar_footer, table[class*="w2calendar_footer"]');

    // div 우선 탐색하되 두 케이스 정확히 구분
    let divFooter = null;
    let tableFooter = null;
    let candidates = calendarRender.querySelectorAll('[class*="w2calendar_footer"]');
    for (let i = 0; i < candidates.length; i++) {
        let tag = candidates[i].tagName.toLowerCase();
        if (tag === 'table' && !tableFooter) tableFooter = candidates[i];
        else if (tag === 'div' && candidates[i].className.indexOf('w2calendar_footer_date') === -1 && candidates[i].className.indexOf('w2calendar_footer_hour') === -1 && candidates[i].className.indexOf('w2calendar_footer_min') === -1 && candidates[i].className.indexOf('w2calendar_footer_sec') === -1 && !divFooter) divFooter = candidates[i];
    }

    let structure = divFooter ? "div 구조" : (tableFooter ? "table 구조" : "Footer 없음");
    let topTag = divFooter ? divFooter.tagName.toLowerCase() : (tableFooter ? tableFooter.tagName.toLowerCase() : '없음');

    // validation: false/미설정 시 table 태그, true 시 div 태그
    wf_body_bottom.getObj("scwin").setReturnValue("[Footer 영역 레이아웃] " + structure + " (최상위 태그=" + topTag + ")");
}



// [공통] Footer 내부 요소 배치 형태 + _div 접미사 CSS 클래스 확인
scwin.getFooterInnerElements = function () {
    let calendarRender = target1.render;
    let footerDivOpt = target1.options.footerDiv;

    let footerEl = null;
    let candidates = calendarRender.querySelectorAll('[class*="w2calendar_footer"]');
    for (let i = 0; i < candidates.length; i++) {
        let cn = candidates[i].className;
        if (cn.indexOf('w2calendar_footer_date') === -1 && cn.indexOf('w2calendar_footer_hour') === -1 && cn.indexOf('w2calendar_footer_min') === -1 && cn.indexOf('w2calendar_footer_sec') === -1) {
            footerEl = candidates[i];
            break;
        }
    }
    if (!footerEl) {
        wf_body_bottom.getObj("scwin").setReturnValue("[Footer 내부 요소] Footer 없음");
        return;
    }

    // 자식 태그 수집
    let children = footerEl.children;
    let tagList = [];
    for (let i = 0; i < children.length; i++) {
        tagList.push(children[i].tagName.toLowerCase());
    }
    // 최대 6개까지만 출력
    let tagSummary = tagList.slice(0, 6).join(', ');
    if (tagList.length > 6) tagSummary += ', ...';

    // validation: false 시 tr/td 셀로 배치 / true 시 span/div/button/a 등으로 직접 배치
    wf_body_bottom.getObj("scwin").setReturnValue("[Footer 내부 요소 배치 형태] 자식 태그 = [" + tagSummary + "]");

    // validation: true 시 '_div' 접미사 CSS 클래스 추가 / false 시 미적용
    let allClass = footerEl.innerHTML;
    let hasDivSuffix = /w2calendar_[a-zA-Z_]+_div\b/.test(allClass);
    let sampleMatch = allClass.match(/w2calendar_[a-zA-Z_]+_div\b/);
    let sampleClass = sampleMatch ? sampleMatch[0] : '없음';
    wf_body_bottom.getObj("scwin").setReturnValue("['_div' 접미사 CSS 클래스 적용 여부] " + (hasDivSuffix ? "적용됨 (예: '" + sampleClass + "')" : "적용되지 않음") + " (footerDiv=" + footerDivOpt + ")");
}



// [공통] Today 버튼 위치 (Header / Footer) - topLayout 무시 동작 + @spec 항목
scwin.getTodayButtonPlacement = function () {
    let calendarRender = target1.render;
    let footerDivOpt = target1.options.footerDiv;
    let topLayoutOpt = target1.options.topLayout;
    let valueTypeOpt = target1.options.calendarValueType;

    let headerEl = calendarRender.querySelector('.w2calendar_header, .w2calendar_picker_header');
    let footerEl = null;
    let candidates = calendarRender.querySelectorAll('[class*="w2calendar_footer"]');
    for (let i = 0; i < candidates.length; i++) {
        let cn = candidates[i].className;
        if (cn.indexOf('w2calendar_footer_date') === -1 && cn.indexOf('w2calendar_footer_hour') === -1 && cn.indexOf('w2calendar_footer_min') === -1 && cn.indexOf('w2calendar_footer_sec') === -1) {
            footerEl = candidates[i];
            break;
        }
    }

    let todayInHeader = headerEl ? headerEl.querySelector('[class*="w2calendar_go_today"], #' + target1.id + '_today_btn') : null;
    let todayInFooter = footerEl ? footerEl.querySelector('[class*="w2calendar_go_today"]') : null;

    let placement;
    if (todayInHeader && !todayInFooter) placement = 'Header';
    else if (!todayInHeader && todayInFooter) placement = 'Footer';
    else if (todayInHeader && todayInFooter) placement = 'Header+Footer';
    else placement = '없음';

    // validation: footerDiv=true 시 topLayout 무시되고 Today 버튼이 항상 Footer 에 표시됨
    // validation: footerDiv=false + calendarValueType=yearMonthDate + topLayout=true → Today 버튼이 Footer 가 아닌 Header 에 배치됨
    wf_body_bottom.getObj("scwin").setReturnValue("[Today 버튼 위치] " + placement + " (footerDiv=" + footerDivOpt + ", topLayout=" + topLayoutOpt + ", calendarValueType='" + valueTypeOpt + "')");
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getAppliedFooterDiv();
    scwin.getFooterLayout();
    scwin.getFooterInnerElements();
    scwin.getTodayButtonPlacement();
}



scwin.target1_onclick = function (e) {
    setTimeout(() => {
        scwin.getAppliedFooterDiv();
    }, 100);
}
